const newItems = [];
for (const item of $input.all()) {
  const binaries = item.binary;
  for (const key in binaries) {
    newItems.push({
      json: { 
        fileName: binaries[key].fileName,
        mimeType: binaries[key].mimeType || 'application/pdf', // fallback
        messageId: item.json.id
      },
      binary: {
        data: binaries[key]
      }
    });
  }
}
return newItems;

const allowedExtensions = ['pdf', 'jpg', 'jpeg', 'png'];

return $input.all().filter(item => {
  const fileName = item.json.fileName || '';
  const ext = fileName.split('.').pop().toLowerCase();
  return allowedExtensions.includes(ext);
});

const newItems = [];
for (const item of $input.all()) {
  const binaries = item.binary;
  for (const key in binaries) {
    newItems.push({
      json: { 
        fileName: binaries[key].fileName,
        mimeType: binaries[key].mimeType || 'application/pdf', // fallback
        messageId: item.json.id
      },
      binary: {
        data: binaries[key]
      }
    });
  }
}
return newItems;

